  "signal_basis": {
    "component_id": "C027.signal_basis",
    "value": "The search retains reductions that repeatedly reproduce failure and continues partitioning them, subject to stopping when no single-component removal preserves failure, further reductions are unsafe or infeasible, or day 9 ends.",
